package configuration

import (
	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"log"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ConfigSavedMsg tells the router the context's configuration changed on disk.
//
// BackendChanged is separate from "something changed" because it is the one
// setting the router cannot honour by rebuilding views: it has to resolve a new
// credentials.Selection first.
type ConfigSavedMsg struct {
	Config       *config.Config
	ThemeChanged bool
	// BackendChanged and GitLabURLChanged are the two settings the router must
	// act on rather than just rebuild views against: one needs a fresh
	// credentials.Selection, the other invalidates a live GitLab session.
	BackendChanged   bool
	GitLabURLChanged bool
}

// Model is the configuration view: every scalar setting in the current context,
// grouped into tabs.
//
// Tabs are not decoration. Twenty-nine fields in one list is unusable, and
// under Rule 135 a tabbed form is the only layout that uses the keyboard
// correctly: Tab is reserved for tabs and ↑↓ for fields, so each key has
// exactly one job.
type Model struct {
	config   *config.Config
	context  string
	sections []section

	activeTab    int
	focusedField int

	// input is bound to the focused text or integer field. There is one, not one
	// per field: the value is read from the config on focus and written back on
	// blur, so the input is a view onto the setting rather than a second copy of
	// it.
	input textinput.Model

	// backendOnFocus is what app.secret_backend held when the field took focus.
	// Changing it is confirmed on the way out rather than on every ←/→, and this
	// is what "No" restores.
	backendOnFocus string
	confirmModal   *sharedcomponents.ConfirmModal

	// footer is the one line of transient state below the tab bar (Rule 128).
	footer sharedcomponents.FooterMessage

	width  int
	height int
}

// New builds the view for the configuration currently loaded.
func New(cfg *config.Config) Model {
	themes, err := theme.ListThemes()
	if err != nil || len(themes) == 0 {
		// A theme directory that cannot be read still leaves the built-in one, so
		// the cycle has something to offer rather than nothing.
		log.Printf("ERROR [configuration] list themes: %v", err)
		themes = []string{"default"}
	}

	in := textinput.New()
	in.CharLimit = 512
	theme.StyleTextInput(&in)

	m := Model{
		config:   cfg,
		context:  config.CurrentContextName(),
		sections: sections(themes, command.ViewNames()),
		input:    in,
	}
	m.bindInput()
	return m
}

// Init satisfies tea.Model. Nothing is loaded asynchronously: the configuration
// is already in memory, which is what makes this view open on its first frame.
func (m Model) Init() tea.Cmd { return nil }

// InEditMode reports whether a text field or the confirm modal has the
// keyboard, which is what stops the router claiming ":", "q" and "?".
func (m Model) InEditMode() bool {
	return m.confirmModal != nil || m.current().takesText()
}

// current returns the focused field.
func (m Model) current() field {
	fields := m.fields()
	if m.focusedField < 0 || m.focusedField >= len(fields) {
		return field{}
	}
	return fields[m.focusedField]
}

// fields returns the active tab's fields.
func (m Model) fields() []field {
	if m.activeTab < 0 || m.activeTab >= len(m.sections) {
		return nil
	}
	return m.sections[m.activeTab].Fields
}

// takesText reports whether a field is edited by typing.
func (f field) takesText() bool {
	return f.Kind == kindText || f.Kind == kindInteger
}

// isDisabled reports whether a scan option is unavailable because a Trivy
// server is configured. The protocol does not support these three, so they are
// forced off rather than silently ignored.
func (m Model) isDisabled(f field) bool {
	return m.serverMode() && serverModeFields[f.Label]
}

func (m Model) serverMode() bool {
	return m.config.Scan.TrivyServer != ""
}

package configuration

import (
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// Update handles messages.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case sharedcomponents.ConfirmModalYesMsg:
		return m.handleBackendConfirmed()

	case sharedcomponents.ConfirmModalNoMsg:
		return m.handleBackendRejected()

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInput()
		return m, nil

	case saveFailedMsg:
		log.Printf("ERROR [configuration] save: %v", msg.err)
		return m, m.footer.Error("Failed to save — check logs")

	case tea.KeyMsg:
		if m.confirmModal != nil {
			var cmd tea.Cmd
			m.confirmModal, cmd = m.confirmModal.Update(msg)
			return m, cmd
		}
		return m.handleKey(msg)
	}

	m.footer.Handle(msg)
	return m, nil
}

// handleKey routes a keystroke. Rule 135 assigns each key exactly one job, and
// a tabbed form is the layout that lets it: Tab switches section, ↑↓ moves
// between fields, ←→ cycles a closed set, Space toggles.
func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "tab":
		return m.switchTab(1)
	case "shift+tab":
		return m.switchTab(-1)
	case "up":
		return m.moveField(-1)
	case "down":
		return m.moveField(1)
	case "left":
		return m.cycleField(-1)
	case "right":
		return m.cycleField(1)
	case " ":
		return m.toggleField()
	}

	// Anything else belongs to the input when a text field has focus. Nothing
	// below this point may claim a printable key: a path or a URL can contain
	// any of them.
	if m.current().takesText() {
		var cmd tea.Cmd
		m.input, cmd = m.input.Update(msg)
		return m, cmd
	}
	return m, nil
}

// switchTab commits the field being edited before leaving, so a value typed and
// abandoned by pressing Tab is not lost.
func (m Model) switchTab(step int) (tea.Model, tea.Cmd) {
	m, cmd, ok := m.commitFocused()
	if !ok {
		return m, cmd
	}

	m.activeTab = (m.activeTab + step + len(m.sections)) % len(m.sections)
	m.focusedField = 0
	m.bindInput()
	return m, cmd
}

// moveField changes the focused field, committing the one being left.
func (m Model) moveField(step int) (tea.Model, tea.Cmd) {
	m, cmd, ok := m.commitFocused()
	if !ok {
		return m, cmd
	}

	fields := m.fields()
	if len(fields) == 0 {
		return m, cmd
	}
	m.focusedField = (m.focusedField + step + len(fields)) % len(fields)
	m.bindInput()
	return m, cmd
}

// commitFocused writes the focused field back to the config and persists.
//
// It returns ok=false when the value was refused, which is what keeps the
// cursor on the offending field: a rejected value must not be left on screen
// while the config quietly holds something else.
func (m Model) commitFocused() (Model, tea.Cmd, bool) {
	f := m.current()

	// Leaving the secret backend with a different value asks first. Confirming
	// on the way out rather than on every ←→ is what makes the field usable.
	if f.Label == secretBackendLabel && *f.str(m.config) != m.backendOnFocus {
		m.confirmModal = sharedcomponents.NewConfirmModal(
			"Change secret backend",
			"Stored secrets are not migrated. The GitLab token and registry passwords will have to be entered again. Continue?")
		return m, nil, false
	}

	if !f.takesText() {
		return m, nil, true
	}

	// Compared by accessor, not by label: two tabs could both hold a field
	// called "URL", and pointer identity cannot be wrong about which setting is
	// in front of the cursor.
	isGitLabURL := f.str != nil && f.str(m.config) == &m.config.GitLab.URL
	before := m.config.GitLab.URL

	if err := f.Apply(m.config, m.input.Value()); err != nil {
		log.Printf("ERROR [configuration] %s: %v", f.Label, err)
		return m, m.footer.Error(err.Error()), false
	}

	if isGitLabURL && m.config.GitLab.URL != before {
		// Said unconditionally rather than only when a session is open: this
		// view holds no session state, and "you will need to sign in again" is
		// true either way. Warning beats forbidding — the same call as for the
		// secret backend.
		return m, tea.Batch(
			m.persist(saved{gitlabURL: true}),
			m.footer.Info("GitLab URL changed — sign in again with :gla"),
		), true
	}
	return m, m.persist(saved{}), true
}

// cycleField advances a closed-set field (Rule 132).
func (m Model) cycleField(step int) (tea.Model, tea.Cmd) {
	f := m.current()
	if f.Kind != kindCycle {
		return m, nil
	}
	f.Cycle(m.config, step)

	// The theme is the one setting whose effect is the screen itself, so it is
	// applied as it is cycled rather than on blur — otherwise the user is
	// choosing blind.
	if f.Label == themeLabel {
		return m, m.persist(saved{theme: true})
	}
	// The backend is confirmed on blur, so nothing is written here.
	if f.Label == secretBackendLabel {
		return m, nil
	}
	return m, m.persist(saved{})
}

// toggleField flips a checkbox. Space is the only key that may (Rule 135).
func (m Model) toggleField() (tea.Model, tea.Cmd) {
	f := m.current()
	if f.Kind != kindToggle {
		return m, nil
	}
	if m.isDisabled(f) {
		// A warning: nothing failed, the setting simply has no meaning here.
		return m, m.footer.Warn("Not supported in Trivy client-server mode")
	}
	f.Toggle(m.config)
	return m, m.persist(saved{})
}

// saved says which settings this write touched that the router has to act on
// rather than merely rebuild views against.
type saved struct {
	theme     bool
	gitlabURL bool
}

// persist applies the cross-field constraints, saves, and tells the router.
func (m Model) persist(what saved) tea.Cmd {
	m.applyServerModeConstraints()

	if err := config.Save(m.config); err != nil {
		log.Printf("ERROR [configuration] save context %s: %v", m.context, err)
		// Reported through the message rather than set here: Update() owns the
		// model, and this is called from it, but the caller decides the footer.
		return func() tea.Msg { return saveFailedMsg{err} }
	}

	cfg := m.config
	return func() tea.Msg {
		return ConfigSavedMsg{Config: cfg, ThemeChanged: what.theme, GitLabURLChanged: what.gitlabURL}
	}
}

// applyServerModeConstraints forces off the three scan options the Trivy
// client-server protocol does not support. A genuine constraint, carried over
// from the security form this view replaces.
func (m *Model) applyServerModeConstraints() {
	if !m.serverMode() {
		return
	}
	m.config.Scan.EnableMisconfig = false
	m.config.Scan.EnableLicense = false
}

type saveFailedMsg struct{ err error }

// handleBackendConfirmed commits the new secret backend and asks the router to
// resolve a fresh credentials.Selection for the context.
func (m Model) handleBackendConfirmed() (tea.Model, tea.Cmd) {
	m.confirmModal = nil
	m.backendOnFocus = m.config.App.SecretBackend

	if err := config.Save(m.config); err != nil {
		log.Printf("ERROR [configuration] save context %s: %v", m.context, err)
		return m, m.footer.Error("Failed to save — check logs")
	}
	cfg := m.config
	return m, func() tea.Msg {
		return ConfigSavedMsg{Config: cfg, BackendChanged: true}
	}
}

// handleBackendRejected puts the setting back. The value was already cycled
// into the config, so declining has to undo it.
func (m Model) handleBackendRejected() (tea.Model, tea.Cmd) {
	m.confirmModal = nil
	m.config.App.SecretBackend = m.backendOnFocus
	return m, nil
}

// bindInput points the shared input at the focused field, or parks it.
func (m *Model) bindInput() {
	f := m.current()

	if f.Label == secretBackendLabel {
		m.backendOnFocus = m.config.App.SecretBackend
	}

	if !f.takesText() {
		m.input.Blur()
		m.input.SetValue("")
		return
	}
	m.resizeInput()
	m.input.SetValue(f.Value(m.config))
	m.input.CursorEnd()
	m.input.Focus()
}

// Labels the view has to recognise. Comparing on the label keeps the field
// table declarative; these two are the only settings that need special
// handling, and naming them here is what makes that visible.
const (
	themeLabel         = "Theme"
	secretBackendLabel = "Secret backend"
)

// resizeInput fits the input between the value column and the right border.
func (m *Model) resizeInput() {
	const focusIndicator, borders = 2, 4
	m.input.Width = max(m.width-m.chevronColumn()-4-focusIndicator-borders, 20)
}

package configuration

import (
	"slices"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
)

func allFields(t *testing.T) []field {
	t.Helper()
	var out []field
	for _, s := range sections([]string{"default", "mocha"}, command.ViewNames()) {
		out = append(out, s.Fields...)
	}
	return out
}

// Every field carries the accessor its kind needs. Twenty-nine settings written
// by hand is exactly where a missing or mismatched accessor hides — the field
// renders, and reads or writes nothing.
func TestEveryFieldCarriesTheAccessorItsKindNeeds(t *testing.T) {
	for _, f := range allFields(t) {
		switch f.Kind {
		case kindText:
			if f.str == nil {
				t.Errorf("%q is a text field with no string accessor", f.Label)
			}
		case kindInteger:
			if f.num == nil {
				t.Errorf("%q is an integer field with no int accessor", f.Label)
			}
			if f.min >= f.max {
				t.Errorf("%q has bounds [%d, %d], which admits nothing", f.Label, f.min, f.max)
			}
		case kindToggle:
			if f.flag == nil {
				t.Errorf("%q is a toggle with no bool accessor", f.Label)
			}
		case kindCycle:
			if f.str == nil {
				t.Errorf("%q is a cycle field with no string accessor", f.Label)
			}
			if len(f.Options) < 2 {
				t.Errorf("%q cycles through %d options; a closed set needs at least two", f.Label, len(f.Options))
			}
		}
	}
}

// Two fields addressing the same setting would make one of them silently
// ineffective — whichever the user did not edit last wins on save.
func TestNoTwoFieldsAddressTheSameSetting(t *testing.T) {
	cfg := config.Default()
	fields := allFields(t)

	for i, a := range fields {
		for _, b := range fields[i+1:] {
			if a.Kind != b.Kind {
				continue
			}
			if samePointer(cfg, a, b) {
				t.Errorf("%q and %q edit the same setting", a.Label, b.Label)
			}
		}
	}
}

func samePointer(c *config.Config, a, b field) bool {
	switch a.Kind {
	case kindToggle:
		return a.flag(c) == b.flag(c)
	case kindInteger:
		return a.num(c) == b.num(c)
	default:
		return a.str(c) == b.str(c)
	}
}

// A cycle field whose current value is outside its options must still move.
// config.Default() is the realistic case: every cycle field's default has to be
// one of the values it offers, or the first ←/→ jumps somewhere arbitrary.
func TestEveryCycleFieldDefaultsToOneOfItsOptions(t *testing.T) {
	cfg := config.Default()

	for _, f := range allFields(t) {
		if f.Kind != kindCycle {
			continue
		}
		v := *f.str(cfg)
		if v == "" {
			continue // applyDefaults fills these at load; Default() leaves some empty
		}
		found := false
		for _, opt := range f.Options {
			if opt == v {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("%q defaults to %q, which is not among %v", f.Label, v, f.Options)
		}
	}
}

// The three settings the router has to special-case are matched by label, so a
// rename that misses one silently drops the behaviour.
func TestTheSpeciallyHandledLabelsExist(t *testing.T) {
	labels := map[string]bool{}
	for _, f := range allFields(t) {
		labels[f.Label] = true
	}

	for _, want := range []string{themeLabel, secretBackendLabel} {
		if !labels[want] {
			t.Errorf("no field is labelled %q, so its special handling is dead", want)
		}
	}
	for want := range serverModeFields {
		if !labels[want] {
			t.Errorf("serverModeFields names %q, which is not a field", want)
		}
	}
}

// ── validation ──────────────────────────────────────────────────────────────

// An out-of-range or unparseable number is refused, not coerced. Coercing to
// zero is how `trivy_server: ":"` reached a config file.
func TestAnIntegerFieldRefusesRatherThanCoerces(t *testing.T) {
	cfg := config.Default()
	f := integer("Jobs", func(c *config.Config) *int { return &c.GitLab.Pull.ParallelJobs }, 1, 32, "")
	cfg.GitLab.Pull.ParallelJobs = 4

	for _, bad := range []string{"", "abc", "0", "33", "-1"} {
		if err := f.Apply(cfg, bad); err == nil {
			t.Errorf("Apply(%q) was accepted", bad)
		}
		if got := cfg.GitLab.Pull.ParallelJobs; got != 4 {
			t.Fatalf("Apply(%q) changed the setting to %d despite failing", bad, got)
		}
	}

	if err := f.Apply(cfg, " 8 "); err != nil {
		t.Errorf("Apply(\" 8 \") = %v, want the surrounding space trimmed and accepted", err)
	}
	if cfg.GitLab.Pull.ParallelJobs != 8 {
		t.Errorf("ParallelJobs = %d, want 8", cfg.GitLab.Pull.ParallelJobs)
	}
}

// The Trivy server address is the one text field with a validator, and it is
// what stops a stray ":" reaching Trivy and failing the whole scan.
func TestTheTrivyServerFieldRefusesAnAddressTrivyCannotParse(t *testing.T) {
	cfg := config.Default()
	f := fieldNamed(t, "Trivy server")

	if err := f.Apply(cfg, ":"); err == nil {
		t.Error("Apply(\":\") was accepted; Trivy fails the whole scan on that")
	}
	if cfg.Scan.TrivyServer != "" {
		t.Errorf("TrivyServer = %q after a refused value", cfg.Scan.TrivyServer)
	}
	if err := f.Apply(cfg, "https://trivy:4954"); err != nil {
		t.Errorf("a valid address was refused: %v", err)
	}
}

// Clearing a field has to be possible: an empty Trivy server is how the user
// leaves client-server mode.
func TestClearingTheTrivyServerIsAllowed(t *testing.T) {
	cfg := config.Default()
	cfg.Scan.TrivyServer = "https://trivy:4954"
	f := fieldNamed(t, "Trivy server")

	if err := f.Apply(cfg, "   "); err != nil {
		t.Fatalf("clearing was refused: %v", err)
	}
	if cfg.Scan.TrivyServer != "" {
		t.Errorf("TrivyServer = %q, want it cleared", cfg.Scan.TrivyServer)
	}
}

func TestCycleWraps(t *testing.T) {
	cfg := config.Default()
	f := fieldNamed(t, "Clone method")
	cfg.GitLab.CloneMethod = "https"

	f.Cycle(cfg, 1)
	if cfg.GitLab.CloneMethod != "ssh" {
		t.Fatalf("after one step: %q, want ssh", cfg.GitLab.CloneMethod)
	}
	f.Cycle(cfg, 1)
	if cfg.GitLab.CloneMethod != "https" {
		t.Errorf("after wrapping: %q, want https", cfg.GitLab.CloneMethod)
	}
	f.Cycle(cfg, -1)
	if cfg.GitLab.CloneMethod != "ssh" {
		t.Errorf("stepping back: %q, want ssh", cfg.GitLab.CloneMethod)
	}
}

// A value outside the closed set lands on the first option rather than being
// carried forward — a hand-edited config file is where this comes from.
func TestCycleFromAnUnknownValueLandsOnTheFirstOption(t *testing.T) {
	cfg := config.Default()
	f := fieldNamed(t, "Clone method")
	cfg.GitLab.CloneMethod = "carrier-pigeon"

	f.Cycle(cfg, 1)

	if cfg.GitLab.CloneMethod != f.Options[1] {
		t.Errorf("got %q, want %q — an unknown value is treated as index 0", cfg.GitLab.CloneMethod, f.Options[1])
	}
}

func fieldNamed(t *testing.T, label string) field {
	t.Helper()
	for _, f := range allFields(t) {
		if f.Label == label {
			return f
		}
	}
	t.Fatalf("no field labelled %q; the labels are %s", label, strings.Join(labelsOf(allFields(t)), ", "))
	return field{}
}

func labelsOf(fields []field) []string {
	out := make([]string, 0, len(fields))
	for _, f := range fields {
		out = append(out, f.Label)
	}
	return out
}

// Every value the Default view field offers has to name a view the router can
// actually open. FullNames() also carries the action commands -- context, theme,
// quit -- so a field built from it offered "quit" as a landing view.
func TestTheDefaultViewFieldOffersOnlyViews(t *testing.T) {
	f := fieldNamed(t, "Default view")

	if len(f.Options) == 0 {
		t.Fatal("the field offers nothing")
	}
	for _, name := range f.Options {
		view, err := command.Parse(name)
		if err != nil || view == "" {
			t.Errorf("%q is offered as a default view but does not name one (%v)", name, err)
		}
	}
	for _, action := range []string{"quit", "theme", "context"} {
		if slices.Contains(f.Options, action) {
			t.Errorf("%q is an action, not a view, and must not be offered", action)
		}
	}
}

package configuration

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Every field in this view calls config.Save on change, so the tests must not
// be pointed at the developer's own ~/.devdesk.
func TestMain(m *testing.M) {
	dir, err := os.MkdirTemp("", "devdesk-configuration-test")
	if err != nil {
		panic(err)
	}
	_ = os.Setenv("HOME", dir)
	_ = os.Setenv("USERPROFILE", dir)
	code := m.Run()
	_ = os.RemoveAll(dir)
	os.Exit(code)
}

func newModel(t *testing.T) Model {
	t.Helper()
	m := New(config.Default())
	updated, _ := m.Update(tea.WindowSizeMsg{Width: 120, Height: 30})
	return updated.(Model)
}

func feed(t *testing.T, m Model, msgs ...tea.Msg) Model {
	t.Helper()
	for _, msg := range msgs {
		updated, _ := m.Update(msg)
		m = updated.(Model)
	}
	return m
}

// focusOn puts the cursor on a named field in the section that holds it.
func focusOn(t *testing.T, m Model, label string) Model {
	t.Helper()
	for tab, s := range m.sections {
		for i, f := range s.Fields {
			if f.Label == label {
				m.activeTab = tab
				m.focusedField = i
				m.bindInput()
				return m
			}
		}
	}
	t.Fatalf("no field labelled %q", label)
	return m
}

// Rule 135 gives each key one job. Tab is reserved for tabs, which is what
// makes a tabbed form the only layout that can use ↑↓ for fields.
func TestTabSwitchesSectionAndArrowsMoveBetweenFields(t *testing.T) {
	m := newModel(t)

	m = feed(t, m, testutil.Key("down"))
	if m.activeTab != 0 {
		t.Errorf("down changed the tab to %d; ↑↓ moves between fields", m.activeTab)
	}
	if m.focusedField != 1 {
		t.Errorf("focusedField = %d after down, want 1", m.focusedField)
	}

	m = feed(t, m, testutil.Key("tab"))
	if m.activeTab != 1 {
		t.Errorf("activeTab = %d after tab, want 1", m.activeTab)
	}
	if m.focusedField != 0 {
		t.Errorf("focusedField = %d after switching section, want the first field", m.focusedField)
	}
}

// Space is the only key that may toggle a checkbox (Rule 135), and enter must
// not.
func TestOnlySpaceTogglesACheckbox(t *testing.T) {
	m := focusOn(t, newModel(t), "Auto refresh")
	before := m.config.Status.AutoRefresh

	m = feed(t, m, testutil.Key("enter"))
	if m.config.Status.AutoRefresh != before {
		t.Error("enter toggled a checkbox")
	}

	m = feed(t, m, testutil.Key(" "))
	if m.config.Status.AutoRefresh == before {
		t.Error("space did not toggle the checkbox")
	}
}

func TestArrowsCycleAClosedSetAndPersist(t *testing.T) {
	m := focusOn(t, newModel(t), "Clone method")
	m.config.GitLab.CloneMethod = "https"

	m = feed(t, m, testutil.Key("right"))

	if m.config.GitLab.CloneMethod != "ssh" {
		t.Errorf("CloneMethod = %q after →, want ssh", m.config.GitLab.CloneMethod)
	}
	reloaded, err := config.Load()
	if err != nil {
		t.Fatalf("reloading the saved config: %v", err)
	}
	if reloaded.GitLab.CloneMethod != "ssh" {
		t.Errorf("the file holds %q; a cycle field persists as it changes", reloaded.GitLab.CloneMethod)
	}
}

// A typed value is written when focus leaves the field, so moving on is what
// commits — there is no save step.
func TestLeavingATextFieldCommitsIt(t *testing.T) {
	m := focusOn(t, newModel(t), "IDE command")
	m.input.SetValue("nvim")

	m = feed(t, m, testutil.Key("down"))

	if m.config.App.IDECommand != "nvim" {
		t.Errorf("IDECommand = %q, want the typed value committed on blur", m.config.App.IDECommand)
	}
}

// A refused value keeps the cursor where it is. Letting focus move would leave
// the rejected text on screen while the config quietly held something else.
func TestARefusedValueKeepsTheCursorOnItsField(t *testing.T) {
	m := focusOn(t, newModel(t), "Parallel jobs")
	was := m.focusedField
	m.config.GitLab.Pull.ParallelJobs = 4
	m.input.SetValue("not-a-number")

	m = feed(t, m, testutil.Key("down"))

	if m.focusedField != was {
		t.Errorf("focus moved to %d despite a refused value", m.focusedField)
	}
	if m.config.GitLab.Pull.ParallelJobs != 4 {
		t.Errorf("ParallelJobs = %d, want the old value kept", m.config.GitLab.Pull.ParallelJobs)
