			groups[f.Group] = append(groups[f.Group], f.Label)
		}
	}

	for _, want := range []string{"Trivy", "Gitleaks"} {
		if len(groups[want]) == 0 {
			t.Errorf("the scan tab has no %q group; it has %v", want, keysOfGroups(groups))
