		t.Errorf("a blurred checkbox renders %q; want two spaces then the box", firstCells(blurred))
	}
}

func firstCells(s string) string {
	r := []rune(s)
	if len(r) > 12 {
		r = r[:12]
	}
	return string(r)
}

// Changing the GitLab URL invalidates a session established against the old
