// Package netcheck answers one question about one target — is this host
// reachable, and is its TLS chain sound — and reports it as a list of checks
// carrying verdicts.
//
// A check is a question that got an answer, not a binary that ran. The
// distinction is the point: one handshake produces four checks (chain,
// hostname, expiry, version), and reachability is answered by two probes. A
// row named after a tool cannot express either, which is why the exit code of
// `nc` and the exit code of `curl` used to render as the same red FAIL.
//
// Nothing here shells out. DNS, ICMP, TCP, TLS and HTTP are answered from this
// process, so they answer for the machine DevDesk runs on. The Docker runner
// they replaced used --network host, which on Docker Desktop is the
// docker-desktop VM's namespace — a different resolver, a different routing
// table, and no knowledge of a VPN the user is actually on.
package netcheck

import (
	"fmt"
	"strings"
)

// Verdict is what a check concluded.
//
// The zero value is Unknown, deliberately: a check that was never filled in
// must not read as a pass. That is the same reasoning behind
// scan.Result.SecretVerdict returning a *bool — "nobody looked" displayed as a
// clean result is a defect, not a nuance.
type Verdict int

const (
	// Unknown means the check could not look. It is not a failure and not a
	// pass; it is the absence of an observation.
	Unknown Verdict = iota
	// NotApplicable means the check has no meaning for this target, or an
	// upstream failure prevented it. The two are told apart by Check.Because.
	NotApplicable
	// OK means the objective is met.
	OK
	// Warn means the objective is met but something about it is off.
	Warn
	// Fail means the objective is not met.
	Fail
)

// String implements fmt.Stringer. The words are what the UI shows, so they are
// English US (Rule 129) and short enough for a table cell.
func (v Verdict) String() string {
	switch v {
	case NotApplicable:
		return "N/A"
	case OK:
		return "OK"
	case Warn:
		return "WARN"
	case Fail:
		return "FAIL"
	default:
		return "UNKNOWN"
	}
}

// severity ranks verdicts for Summarize. Fail outranks Unknown because a known
// failure is more actionable than an absent observation; Unknown outranks Warn
// because not having looked is worse than having looked and found a blemish.
// NotApplicable ranks lowest: it never colours a headline.
func (v Verdict) severity() int {
	switch v {
	case Fail:
		return 4
	case Unknown:
		return 3
	case Warn:
		return 2
	case OK:
		return 1
	default:
		return 0
	}
}

// CheckID identifies one question. It is stable: the explanation table in PR 2
// and any serialization are keyed on it.
type CheckID string

const (
	CheckResolve      CheckID = "resolve"
	CheckReverseDNS   CheckID = "reverse-dns"
	CheckICMP         CheckID = "icmp"
	CheckTCP          CheckID = "tcp"
	CheckTLSHandshake CheckID = "tls-handshake"
	CheckTLSChain     CheckID = "tls-chain"
	CheckTLSHostname  CheckID = "tls-hostname"
	CheckTLSExpiry    CheckID = "tls-expiry"
	CheckTLSVersion   CheckID = "tls-version"
	CheckHTTP         CheckID = "http"
)

// StageID identifies a layer of the pipeline.
type StageID string

const (
	StageResolve StageID = "resolve"
	StageReach   StageID = "reach"
	StageConnect StageID = "connect"
	StageTLS     StageID = "tls"
	StageHTTP    StageID = "http"
)

// Fact is one observed value, shown in a check's detail pane.
type Fact struct {
	Key   string
	Value string
}

// Check is one answered question.
type Check struct {
	ID      CheckID
	Stage   StageID
	Title   string
	Verdict Verdict
	// Summary is the one line the results table shows. It states what was
	// observed, never what to do about it — the advice belongs to the
	// explanation layer, which is keyed on ID.
	Summary string
	Facts   []Fact
	// Because is set only when Verdict is NotApplicable *and* the cause was an
	// upstream failure. Empty on a NotApplicable that simply has no meaning
	// here, which is what separates "blocked" from "irrelevant".
	Because CheckID
	// Reason is a stable sub-code for a verdict that has more than one cause.
	//
	// It exists because the remedies differ where the verdict does not: a chain
	// that fails because the leaf is self-signed, because the server sent no
	// intermediates, and because the root is unknown are one Fail with three
	// different things to go and do. Summary already says which in prose;
	// Reason is what an explanation — or a serialization — can switch on.
	//
	// Empty is the common case: most verdicts have exactly one cause.
	Reason Reason
}

// Reason discriminates the causes of a verdict that has several. It is stable:
// the guidance table is keyed on it.
type Reason string

const (
	// Certificate chain
	ReasonSelfSigned      Reason = "self-signed"
	ReasonNoIntermediates Reason = "no-intermediates"
	ReasonUntrustedRoot   Reason = "untrusted-root"
	ReasonChainIncomplete Reason = "chain-incomplete"

	// Certificate validity
	ReasonExpired     Reason = "expired"
	ReasonNotYetValid Reason = "not-yet-valid"

	// ICMP
	ReasonNoReply     Reason = "no-reply"
	ReasonPartialLoss Reason = "partial-loss"

	// TLS handshake
	ReasonNotTLS Reason = "not-tls"
)

// fact appends an observed value, skipping empty ones so a detail pane never
// shows a key with nothing beside it.
func (c *Check) fact(key, value string) {
	if strings.TrimSpace(value) == "" {
		return
	}
	c.Facts = append(c.Facts, Fact{Key: key, Value: value})
}

// Target is what is being checked.
type Target struct {
	Host string
	Port int
	// Resolver is the nameserver to query, "host" or "host:port". Empty means
	// the system resolver — which is the answer the user actually cares about,
	// so it is the default rather than a fallback.
	Resolver string
}

// Addr returns the host:port form used to dial.
func (t Target) Addr() string {
	return fmt.Sprintf("%s:%d", t.Host, t.Port)
}

// Validate rejects a target the stages cannot act on. The view validates too,
// but this is a package boundary and external data is not trusted at one.
func (t Target) Validate() error {
	if strings.TrimSpace(t.Host) == "" {
		return fmt.Errorf("target is required")
	}
	if t.Port < 1 || t.Port > 65535 {
		return fmt.Errorf("port must be a number between 1 and 65535")
	}
	return nil
}

// Results holds the checks a run produced, in pipeline order.
//
// It is a type rather than a []Check because a stage needs to read what came
// before it — the HTTP stage picks its scheme from the handshake's outcome —
// and because the order is meaningful and must not be re-derived by a caller.
type Results struct {
	checks []Check
	index  map[CheckID]int
}

func (r *Results) add(c Check) {
	if r.index == nil {
		r.index = make(map[CheckID]int)
	}
	if i, ok := r.index[c.ID]; ok {
		r.checks[i] = c
		return
	}
	r.index[c.ID] = len(r.checks)
	r.checks = append(r.checks, c)
}

// clone returns a deep-enough copy: the slice and the index are fresh, so
// adding to the copy cannot write into the original's backing array. It is what
// makes RunStep safe to call on a goroutine while the caller still holds the
// previous value.
func (r Results) clone() Results {
	out := Results{
		checks: make([]Check, len(r.checks)),
		index:  make(map[CheckID]int, len(r.index)),
	}
	copy(out.checks, r.checks)
	for k, v := range r.index {
		out.index[k] = v
	}
	return out
}

// ResultsOf assembles a Results from checks that are already known.
//
// It exists for the callers that receive checks rather than produce them: a
// view driving the pipeline through messages, a test describing a situation,
// and — later — anything reading a serialized run back.
func ResultsOf(checks ...Check) Results {
	var r Results
	for _, c := range checks {
		r.add(c)
	}
	return r
}

// All returns the checks in pipeline order.
func (r Results) All() []Check { return r.checks }

// Get returns one check by ID.
func (r Results) Get(id CheckID) (Check, bool) {
	i, ok := r.index[id]
	if !ok {
		return Check{}, false
	}
	return r.checks[i], true
}

// VerdictOf returns a check's verdict, or Unknown when it was never produced —
// which is the honest answer for a question nobody asked.
func (r Results) VerdictOf(id CheckID) Verdict {
	c, ok := r.Get(id)
	if !ok {
		return Unknown
	}
	return c.Verdict
}

// Summarize folds the checks into the one verdict the header shows.
//
// It is the only thing that computes an aggregate. scan.Categorize and
// SecretVerdict both exist because two rules answered one question and
// disagreed; the symptom was identical each time — something counted in one
// place and absent from another.
func Summarize(checks []Check) Verdict {
	worst := OK
	seen := false
	for _, c := range checks {
		if c.Verdict == NotApplicable {
			continue
		}
		seen = true
		if c.Verdict.severity() > worst.severity() {
			worst = c.Verdict
		}
	}
	if !seen {
		return Unknown
	}
	return worst
}

package netcheck

import (
	"context"
	"errors"
)

// errNotTLSConn is returned when a dialer hands back something that is not a
// TLS connection. It cannot happen with tls.Dialer, and is reported rather
// than asserted so a future dialer swap fails loudly.
var errNotTLSConn = errors.New("connection is not a TLS connection")

// checkTitles is the one place a check's human name is written. The skip path
// needs a title for a check that never ran, so it cannot come from the stage
// that would have produced it.
var checkTitles = map[CheckID]string{
	CheckResolve:      "DNS resolution",
	CheckReverseDNS:   "Reverse DNS",
	CheckICMP:         "ICMP echo",
	CheckTCP:          "TCP connect",
	CheckTLSHandshake: "TLS handshake",
	CheckTLSChain:     "Certificate chain",
	CheckTLSHostname:  "Hostname match",
	CheckTLSExpiry:    "Certificate expiry",
	CheckTLSVersion:   "TLS version",
	CheckHTTP:         "HTTP response",
}

// stage is one layer of the pipeline.
type stage struct {
	id        StageID
	dependsOn StageID
	// gate is the check whose verdict decides whether dependent stages run.
	// A stage that gates nothing leaves it empty — which is a decision, not an
	// omission, at both sites that use it.
	gate CheckID
	// produces is what run returns, declared so the skip path can name the
	// checks that never ran. TestEveryStageProducesWhatItDeclares keeps the two
	// in step.
	produces []CheckID
	run      func(ctx context.Context, t Target, env Env, prior *Results) []Check
}

// stageTitles names a stage for a progress line. A stage is what the user waits
// on, so it is what the wait is labelled with.
var stageTitles = map[StageID]string{
	StageResolve: "Resolving the name",
	StageReach:   "Probing reachability",
	StageConnect: "Connecting to the port",
	StageTLS:     "Inspecting the certificate",
	StageHTTP:    "Asking for a response",
}

// StageTitle names a stage, for a caller reporting progress.
func StageTitle(id StageID) string { return stageTitles[id] }

// Steps returns the pipeline in order.
//
// It exists so an interactive caller can run one stage at a time and say which
// question is being asked. That matters most in the case worth diagnosing: an
// unreachable host spends its timeouts one after another, and a spinner with
// nothing beside it is indistinguishable from a hang — §3.16's lesson.
func Steps() []StageID {
	all := stages()
	out := make([]StageID, 0, len(all))
	for _, s := range all {
		out = append(out, s.id)
	}
	return out
}

// RunStep runs one stage against the results so far and returns the updated
// set. It applies the same skip rule Run does — there is one cascade, not two.
//
// prior is never modified: the returned Results is built from a copy, so a
// caller may hold the previous value across a goroutine boundary without
// sharing anything with this call. That is what lets a Bubble Tea view chain
// the stages through messages and never touch a model from inside a Cmd
// (Rule 110).
func RunStep(ctx context.Context, t Target, env Env, id StageID, prior Results) Results {
	res := prior.clone()
	all := stages()
	gateOf := gatesOf(all)

	for _, s := range all {
		if s.id != id {
			continue
		}
		runStage(ctx, s, gateOf, t, env, &res)
	}
	return res
}

// stages is the pipeline, in order.
//
// Two of the dependencies are worth reading twice:
//
//   - reach gates nothing. ICMP is filtered on a large share of hosts that are
//     perfectly reachable, so a silent ping must not cascade NotApplicable over
//     the TLS checks — which is the whole question the user came to ask.
//   - http depends on connect, not on tls. A broken chain must not hide whether
//     the service answers: "the app works, the certificate is what is wrong" is
//     useful, and the certificate problem has rows of its own.
func stages() []stage {
	return []stage{
		{
			id:       StageResolve,
			gate:     CheckResolve,
			produces: []CheckID{CheckResolve, CheckReverseDNS},
			run:      runResolve,
		},
		{
			id:        StageReach,
			dependsOn: StageResolve,
			produces:  []CheckID{CheckICMP},
			run:       runReach,
		},
		{
			id:        StageConnect,
			dependsOn: StageResolve,
			gate:      CheckTCP,
			produces:  []CheckID{CheckTCP},
			run:       runConnect,
		},
		{
			id:        StageTLS,
			dependsOn: StageConnect,
			produces: []CheckID{
				CheckTLSHandshake, CheckTLSChain,
				CheckTLSHostname, CheckTLSExpiry, CheckTLSVersion,
			},
			run: runTLS,
		},
		{
			id:        StageHTTP,
			dependsOn: StageConnect,
			produces:  []CheckID{CheckHTTP},
			run:       runHTTP,
		},
	}
}

// Run walks the pipeline and returns every check, in order.
//
// A stage whose dependency failed does not run: its checks come back
// NotApplicable carrying the check that blocked them. That is what turns seven
// red rows into one red row and a named point of rupture.
func Run(ctx context.Context, t Target, env Env) (Results, error) {
	var res Results
	if err := t.Validate(); err != nil {
		return res, err
	}

	all := stages()
	gateOf := gatesOf(all)
	for _, s := range all {
		runStage(ctx, s, gateOf, t, env, &res)
	}
	return res, nil
}

// gatesOf indexes the gate each stage provides.
func gatesOf(all []stage) map[StageID]CheckID {
	out := make(map[StageID]CheckID, len(all))
	for _, s := range all {
		if s.gate != "" {
			out[s.id] = s.gate
		}
	}
	return out
}

// runStage is the one place a stage is either run, skipped or cancelled, so
// Run and RunStep cannot drift apart on what any of the three means.
func runStage(ctx context.Context, s stage, gateOf map[StageID]CheckID, t Target, env Env, res *Results) {
	if ctx.Err() != nil {
		addPlaceholders(res, s, Unknown, "", "Cancelled before this check ran")
		return
	}
	if blocker, ok := blockedBy(s, gateOf, *res); ok {
		addPlaceholders(res, s, NotApplicable, blocker,
			"Skipped — "+checkTitles[blocker]+" did not succeed")
		return
	}
	for _, c := range s.run(ctx, t, env, res) {
		res.add(c)
	}
}

// blockedBy reports whether s must be skipped, and which check blocked it.
//
// Fail and Unknown block. NotApplicable blocks only when it was itself caused
// by an upstream failure — which is precisely what Check.Because distinguishes,
// and the reason it is a field rather than a flag:
//
//   - a literal IP address makes the resolution check NotApplicable with no
//     Because, and everything below it is perfectly meaningful;
//   - a resolution that failed makes the TCP check NotApplicable *because* of
//     it, and the TLS checks below are just as unanswerable.
//
// The original cause is passed along rather than the immediate one. "Blocked by
// DNS resolution" is actionable; "blocked by a check that was itself blocked"
// sends the user hopping between rows to find the one thing that broke.
func blockedBy(s stage, gateOf map[StageID]CheckID, res Results) (CheckID, bool) {
	if s.dependsOn == "" {
		return "", false
	}
	gate, ok := gateOf[s.dependsOn]
	if !ok {
		return "", false
	}
	switch res.VerdictOf(gate) {
	case Fail, Unknown:
		return gate, true
	case NotApplicable:
		if c, found := res.Get(gate); found && c.Because != "" {
			return c.Because, true
		}
		return "", false
	default:
		return "", false
	}
}

// addPlaceholders records the checks a skipped stage would have produced, so a
// question that was never asked is visible as such rather than absent.
func addPlaceholders(res *Results, s stage, v Verdict, because CheckID, summary string) {
	for _, id := range s.produces {
		res.add(Check{
			ID:      id,
			Stage:   s.id,
			Title:   checkTitles[id],
			Verdict: v,
			Summary: summary,
			Because: because,
		})
	}
}

// newCheck starts a check with its declared title, so no stage spells one out.
func newCheck(id CheckID, s StageID, v Verdict, summary string) Check {
	return Check{ID: id, Stage: s, Title: checkTitles[id], Verdict: v, Summary: summary}
}

package netcheck

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"net"
	"net/http"
	"runtime"
	"time"

	probing "github.com/prometheus-community/pro-bing"
)

// Timeouts and counts are named constants, not configuration. Every scalar
// added to the config is a row in configuration/fields.go and its tests; these
// become settings when someone asks for them, not before.
const (
	resolveTimeout = 5 * time.Second
	dialTimeout    = 5 * time.Second
	tlsTimeout     = 8 * time.Second
	httpTimeout    = 8 * time.Second
	pingTimeout    = 4 * time.Second
	pingCount      = 3

	// expiryWarnWindow is how close a certificate may come to expiring before
	// the check warns. Thirty days is a renewal cycle: past it, nobody has
	// started renewing yet, so warning earlier is noise.
	expiryWarnWindow = 30 * 24 * time.Hour
)

// PingStats is what one ICMP probe run observed.
type PingStats struct {
	Sent     int
	Received int
	AvgRTT   time.Duration
}

// HTTPResult is what one HEAD request observed.
type HTTPResult struct {
	Status int
	Server string
	// TLS reports whether the request was made over TLS, so the check can say
	// which scheme it actually spoke rather than which one was intended.
	TLS bool
}

// Env is the seam every stage reaches the network through.
//
// internal/docker's dockerRunner is the precedent, with one difference: that
// one is a package-level var tests swap, which forces those tests to run
// serially. Here the seam is a parameter, so a fake is per-call and the
// package stays safe to use concurrently.
type Env interface {
	// Resolve returns the addresses host maps to. resolver is a nameserver
	// ("host" or "host:port"); empty means the system resolver.
	Resolve(ctx context.Context, host, resolver string) ([]net.IP, error)
	// ReverseLookup returns the names ip maps back to.
	ReverseLookup(ctx context.Context, ip, resolver string) ([]string, error)
	// Ping sends count ICMP echo requests.
	Ping(ctx context.Context, host string, count int) (PingStats, error)
	// DialTCP opens and immediately closes a TCP connection, reporting how
	// long the handshake took. It returns no connection: the stage wants to
	// know whether the port answers, and handing back a Conn would make every
	// fake responsible for closing it.
	DialTCP(ctx context.Context, addr string) (time.Duration, error)
	// Handshake completes a TLS handshake without verifying the chain.
	Handshake(ctx context.Context, addr, serverName string) (*tls.ConnectionState, error)
	// Head issues an HTTP HEAD request.
	Head(ctx context.Context, url string) (HTTPResult, error)
	// TrustRoots is the store the chain is verified against. nil means the
	// host's own, which is the only answer that matters in production — a
	// chain "verifies" only against a store somebody actually uses.
	//
	// It is on the seam rather than hidden inside the stage because which
	// store to trust is a property of the environment, and because a test
	// cannot get a certificate it minted into the machine's root store.
	TrustRoots() *x509.CertPool
	// Now is the clock, injected so an expiry test does not depend on the day
	// it runs.
	Now() time.Time
}

// systemEnv is the production Env: it answers from this process, on this
// machine's network stack.
type systemEnv struct{}

// SystemEnv returns the Env that talks to the real network.
func SystemEnv() Env { return systemEnv{} }

func (systemEnv) Now() time.Time { return time.Now() }

// TrustRoots returns nil: the host's own trust store is the one whose verdict
// the user lives with.
func (systemEnv) TrustRoots() *x509.CertPool { return nil }

// resolverFor builds a net.Resolver aimed at a specific nameserver, or the
// system one when none is named. The pattern mirrors status/dns_checker.go —
// PreferGo plus a Dial that redirects every query — which is the only way to
// query a chosen server without a DNS library.
func resolverFor(nameserver string) *net.Resolver {
	if nameserver == "" {
		return &net.Resolver{}
	}
	addr := nameserver
	if _, _, err := net.SplitHostPort(addr); err != nil {
		addr = net.JoinHostPort(nameserver, "53")
	}
	return &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, _ string) (net.Conn, error) {
			d := net.Dialer{Timeout: resolveTimeout}
			return d.DialContext(ctx, network, addr)
		},
	}
}

func (systemEnv) Resolve(ctx context.Context, host, resolver string) ([]net.IP, error) {
	ctx, cancel := context.WithTimeout(ctx, resolveTimeout)
	defer cancel()

	addrs, err := resolverFor(resolver).LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}
	ips := make([]net.IP, 0, len(addrs))
	for _, a := range addrs {
		ips = append(ips, a.IP)
	}
	return ips, nil
}

func (systemEnv) ReverseLookup(ctx context.Context, ip, resolver string) ([]string, error) {
	ctx, cancel := context.WithTimeout(ctx, resolveTimeout)
	defer cancel()
	return resolverFor(resolver).LookupAddr(ctx, ip)
}

func (systemEnv) Ping(ctx context.Context, host string, count int) (PingStats, error) {
	pinger, err := probing.NewPinger(host)
	if err != nil {
		return PingStats{}, err
	}
	pinger.Count = count
	pinger.Timeout = pingTimeout
	// Windows has no unprivileged ICMP socket: pro-bing's UDP mode silently
	// receives nothing there, which reads as "host down" on a host that is up.
	// Elsewhere unprivileged is right, because DevDesk must not need root.
	pinger.SetPrivileged(runtime.GOOS == "windows")

	if err := pinger.RunWithContext(ctx); err != nil {
		return PingStats{}, err
	}
	s := pinger.Statistics()
	return PingStats{Sent: s.PacketsSent, Received: s.PacketsRecv, AvgRTT: s.AvgRtt}, nil
}

func (systemEnv) DialTCP(ctx context.Context, addr string) (time.Duration, error) {
	ctx, cancel := context.WithTimeout(ctx, dialTimeout)
	defer cancel()

	start := time.Now()
	d := net.Dialer{}
	conn, err := d.DialContext(ctx, "tcp", addr)
	if err != nil {
		return 0, err
	}
	elapsed := time.Since(start)
	_ = conn.Close() //nolint:errcheck // the probe is the dial; a close error says nothing about it
	return elapsed, nil
}

// Handshake deliberately does not verify the chain.
//
// Verification is the tls stage's job, so that it can report *which* part
// failed — untrusted root, missing intermediate, wrong hostname, expired — as
// four separate checks. Letting crypto/tls abort the handshake would collapse
// all four into one error string and lose the certificate we need to inspect,
// which is the defect this package exists to fix: the old check greped the
// leaf and never looked at the chain at all.
func (systemEnv) Handshake(ctx context.Context, addr, serverName string) (*tls.ConnectionState, error) {
	ctx, cancel := context.WithTimeout(ctx, tlsTimeout)
	defer cancel()

	d := tls.Dialer{
		NetDialer: &net.Dialer{},
		Config: &tls.Config{
			InsecureSkipVerify: true, //nolint:gosec // G402: see the doc comment — the tls stage verifies, and must see a bad chain to describe it
			ServerName:         serverName,
			MinVersion:         tls.VersionTLS10, // probing, not securing: report old versions rather than refuse them
		},
	}
	conn, err := d.DialContext(ctx, "tcp", addr)
	if err != nil {
		return nil, err
	}
	defer func() { _ = conn.Close() }()

	tlsConn, ok := conn.(*tls.Conn)
	if !ok {
		return nil, errNotTLSConn
	}
	state := tlsConn.ConnectionState()
	return &state, nil
}

// Head does not verify the chain either, and for a reason worth stating: a
// certificate problem must not hide whether the service answers. "The app
// works, the cert is what is broken" is a useful thing to be told, and the TLS
// checks report the cert problem on rows of their own.
func (systemEnv) Head(ctx context.Context, url string) (HTTPResult, error) {
	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
	defer cancel()

	client := &http.Client{
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{
				InsecureSkipVerify: true, //nolint:gosec // G402: see the doc comment — chain problems are reported by the tls stage, not by hiding the response
				MinVersion:         tls.VersionTLS10,
			},
		},
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse // the first answer is the observation; a redirect chain is a different question
		},
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodHead, url, nil)
	if err != nil {
		return HTTPResult{}, err
	}
	resp, err := client.Do(req)
	if err != nil {
		return HTTPResult{}, err
	}
	defer func() { _ = resp.Body.Close() }()

	return HTTPResult{
		Status: resp.StatusCode,
		Server: resp.Header.Get("Server"),
		TLS:    resp.TLS != nil,
	}, nil
}

// Load charge la configuration depuis le contexte actuel
func Load() (*Config, error) {
	ctx, err := GetCurrentContext()
	if err != nil {
		// Fallback to default on error
		ctx = "default"
	}

	cfg, err := LoadContext(ctx)
	if err != nil {
		// Si le fichier n'existe pas, retourner config par défaut
		if os.IsNotExist(err) || strings.Contains(err.Error(), "does not exist") {
			return Default(), nil
		}
		// Sinon (parsing error, permission error, etc.), propager l'erreur
		return nil, err
	}

	return cfg, nil
}

// applyDefaults applique les valeurs par défaut à une configuration.
// Retourne une erreur quand le fichier ne peut pas être normalisé — aujourd'hui
// uniquement pour les registres (slug dupliqué, groupe parent absent).
func applyDefaults(cfg *Config) error {
	homeDir, _ := os.UserHomeDir()

	// "dark" was a third name for the built-in theme: LoadTheme accepts "",
	// "dark" and "default" alike, but ListThemes only ever offers "default", so
	// a config saying "dark" named a theme no picker could show. Normalised at
	// load; LoadTheme still accepts the old name for a file not yet rewritten.
	if cfg.App.Theme == "" || cfg.App.Theme == "dark" {
		cfg.App.Theme = "default"
	}
	if cfg.App.LogFile == "" {
		cfg.App.LogFile = filepath.Join(homeDir, ".devdesk", "devdesk.log")
	}
	if cfg.App.DefaultView == "" {
		cfg.App.DefaultView = "dashboard"
	}
	if cfg.App.WorkspacesDir == "" {
		cfg.App.WorkspacesDir = filepath.Join(homeDir, "workspaces")
	}
	if cfg.App.IDECommand == "" {
		cfg.App.IDECommand = "code"
	}
	// Left empty, credentials.Select already treats this as "auto"; naming it
	// keeps the setting inside the closed set the configuration view cycles
	// through, so the first arrow press does not jump somewhere arbitrary.
	if cfg.App.SecretBackend == "" {
		cfg.App.SecretBackend = "auto"
	}
	if cfg.Status.RefreshInterval == 0 {
		cfg.Status.RefreshInterval = 10
	}
	if cfg.Status.Timeout == 0 {
		cfg.Status.Timeout = 5
	}
	if cfg.GitLab.DefaultVisibility == "" {
		cfg.GitLab.DefaultVisibility = "private"
	}
	if cfg.GitLab.CloneMethod == "" {
		cfg.GitLab.CloneMethod = "https"
	}
	if cfg.GitLab.Pull.ParallelJobs == 0 {
		cfg.GitLab.Pull.ParallelJobs = 4
	}
	if cfg.Registry.CacheDir == "" {
		cfg.Registry.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "templates")
	}
	// Migrate old single-registry config to the new Registries list
	if cfg.Registry.URL != "" && len(cfg.Registry.Registries) == 0 {
		cfg.Registry.Registries = []RegistryItem{{
			URL:      cfg.Registry.URL,
			Username: cfg.Registry.Username,
			AuthMode: AuthCredentials,
		}}
	}
	if cfg.Scan.CacheDir == "" {
		cfg.Scan.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "scans")
	}
	if cfg.Scan.MaxCachedReports == 0 {
		cfg.Scan.MaxCachedReports = 50
	}
	if cfg.Scan.Timeout == 0 {
		cfg.Scan.Timeout = 300
	}
	if cfg.Scan.MaxConcurrentScans == 0 {
		cfg.Scan.MaxConcurrentScans = 3
	}
	// Auto is the historical resolution, so a config that predates the setting
	// keeps behaving exactly as it did.
	if cfg.Scan.TrivySource == "" {
		cfg.Scan.TrivySource = ToolSourceAuto
	}
	if cfg.Scan.GitleaksSource == "" {
		cfg.Scan.GitleaksSource = ToolSourceAuto
	}

	if cfg.Docker.NetworkToolImage == "" {
		cfg.Docker.NetworkToolImage = "nicolaka/netshoot"
	}

	// Backward compat: configs created before the scan-option booleans were introduced
	// will have all of them at Go's zero value (false). Treat "all disabled" as
	// "never configured" and apply sensible defaults so scans work out of the box.
	if !cfg.Scan.EnableVuln && !cfg.Scan.EnableSecret && !cfg.Scan.EnableMisconfig && !cfg.Scan.EnableLicense {
		cfg.Scan.EnableVuln = true
		cfg.Scan.EnableSecret = true
	}

	// Last, so that the registry migrated from the legacy single-registry keys
	// above gets a slug like every other one.
	return normalizeRegistries(cfg.Registry.Registries)
}

// Default retourne la configuration par défaut
func Default() *Config {
	homeDir, _ := os.UserHomeDir()
	return &Config{
		App: AppConfig{
			Theme:         "default",
			LogFile:       filepath.Join(homeDir, ".devdesk", "devdesk.log"),
			DefaultView:   "dashboard",
			WorkspacesDir: filepath.Join(homeDir, "workspaces"),
			IDECommand:    "code",
			SecretBackend: "auto",
		},
		Status: StatusConfig{
			RefreshInterval: 10,
			AutoRefresh:     true,
			Timeout:         5,
			Components:      []ComponentConfig{},
		},
		GitLab: GitLabConfig{
			DefaultVisibility: "private",
			CloneMethod:       "https",
			Pull: GitLabPullConfig{
				ParallelJobs:    4,
				IncludeArchived: false,
			},
		},
		Registry: RegistryConfig{
			CacheDir: filepath.Join(homeDir, ".devdesk", "cache", "templates"),
		},
		Scan: ScanConfig{
